            { t: 'מחשבים SHA-256 לקובץ ומשווים לערך שמפורסם באתר הרשמי של היצרן', ok: true, why: 'נכון — שימוש קלאסי ב-hash לבדיקת **שלמות**. עוד יותר טוב: לאמת גם את החתימה הדיגיטלית של היצרן.' },
            { t: 'בודקים שגודל הקובץ נראה הגיוני', why: 'תוקף יכול לייצר קובץ זדוני בגודל זהה בדיוק.' },
            { t: 'ממירים את הקובץ ל-Base64', why: 'Base64 רק משנה ייצוג — הוא לא בודק כלום.' },
            { t: 'סורקים פעם אחת באנטי-וירוס וסומכים', why: 'אנטי-וירוס לא מזהה כל שינוי — במיוחד בתקיפות שרשרת אספקה.' }
