            { t: 'from="DHL Express" <track@dhl-parcel-il.top>  spf=pass dkim=pass  attach=tracking.zip', bad: true, why: 'שם תצוגה של DHL, דומיין .top שאינו של DHL וקובץ ZIP — מתכון קלאסי להפצת נוזקה (T1566.001).' }
