  tip: 'כשאתה כותב JavaScript: אם הנתון הגיע ממשתמש, הוא נכנס לדף רק דרך `textContent` (או דרך ספריית תבניות שמקודדת אוטומטית). `innerHTML` עם קלט משתמש = באג אבטחה.',
  standards: ['OWASP Top 10:2025 A05 – Injection', 'CWE-79 – Cross-site Scripting', 'OWASP XSS Prevention Cheat Sheet'],
