function examUnlocked() { return state.unlockAll || DAYS.every(d => state.days[d.id]?.done); }

function renderExam(v) {
  v.append(h('div', { class: 'crumbs' }, h('a', { href: '#home' }, '→ חזרה למסלול')), h('h1', null, '🎓 המבחן המסכם'));
  if (!examUnlocked()) {
    const done = DAYS.filter(d => state.days[d.id]?.done).length;
    v.append(h('section', { class: 'card' }, h('h3', null, '🔒 המבחן נפתח בסוף המסלול'),
      h('p', null, `השלמת ${done} מתוך 14 ימים. המבחן ייפתח כשתשלים את כולם (או אם תבחר "פתח את כל הימים" בהגדרות).`),
      progressBar(Math.round(done / 14 * 100), 'התקדמות במסלול'),
      h('div', { class: 'row', style: 'margin-top:12px' }, h('a', { class: 'btn primary', href: `#day-${nextDay().id}` }, `ליום ${nextDay().id}`))));
    return;
  }
  const stage = h('div');
  v.append(stage);
  showIntro();

  function showIntro() {
    stage.replaceChildren(h('section', { class: 'card' },
      h('p', null, rich(`${EXAM.length} שאלות על כל המסלול. ציון עובר: **${EXAM_PASS}**. אין הגבלת זמן, והמשוב המלא מגיע בסוף.`)),
      state.exam.best ? h('p', { class: 'muted' }, `הציון הטוב ביותר שלך: ${state.exam.best}${state.exam.passed ? ' ✅ עברת' : ''}`) : null,
      h('button', { class: 'btn primary big', type: 'button', onclick: start }, state.exam.best ? '🔁 נסה שוב' : '🚀 התחל מבחן')),
      state.exam.passed ? certificate(state.exam.best) : null);
  }

  function start() {
    const qs = shuffle(EXAM).map(q => ({ ...q, options: shuffle(q.options) }));
    const answers = [];
    let i = 0;
    const show = () => {
      const q = qs[i];
      const dots = h('div', { class: 'stepdots', 'aria-hidden': 'true' }, qs.map((_, k) => h('span', { class: k < i ? 'on' : k === i ? 'cur' : '' })));
      const opts = h('div', { class: 'options' }, q.options.map(o => h('button', { class: 'opt', type: 'button', onclick: () => {
        answers[i] = o; i++;
        if (i < qs.length) show(); else finish(qs, answers);
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } }, rich(o.t))));
      stage.replaceChildren(h('section', { class: 'card exam' },
        h('div', { class: 'muted small' }, `שאלה ${i + 1} מתוך ${qs.length} · יום ${q.day}`), dots,
        h('p', { class: 'q' }, rich(q.q)), opts));
    };
    show();
  }

  function finish(qs, answers) {
    const right = answers.filter(a => a.ok).length;
    const score = Math.round(right / qs.length * 100);
    const passed = score >= EXAM_PASS;
    const firstPass = passed && !state.exam.passed;
    state.exam.best = Math.max(state.exam.best, score);
    if (passed) state.exam.passed = true;
    save();
    if (firstPass) { addXP(100, 'עברת את המבחן המסכם!'); confetti(); setTimeout(confetti, 700); mascot('wow', 'עברת! 🎓 אתה רשמית מגן רשתות. אני גאה בך!', 9000); }
    else if (passed) mascot('happy', `ציון ${score} — מצוין!`, 5000);
    else mascot('think', `ציון ${score}. עוד קצת חזרה על הימים המסומנים וזה שלך 💪`, 7000);
    checkBadges(); save(); renderHeader();
    const wrong = qs.map((q, k) => ({ q, a: answers[k] })).filter(x => !x.a.ok);
    stage.replaceChildren(
      h('section', { class: 'card', style: 'text-align:center' },
        h('div', { class: 'score' }, `${score}`),
        h('h2', null, passed ? '✅ עברת!' : '📚 עוד לא — אבל קרוב'),
        h('p', { class: 'muted' }, `${right} תשובות נכונות מתוך ${qs.length} · ציון עובר: ${EXAM_PASS}`),
        h('div', { class: 'row', style: 'justify-content:center' },
          h('button', { class: 'btn primary', type: 'button', onclick: start }, '🔁 נסה שוב'),
          h('a', { class: 'btn', href: '#home' }, '🏠 למסלול'))),
      passed ? certificate(state.exam.best) : null,
      wrong.length ? h('section', { class: 'card' }, h('h3', null, `🔎 מה כדאי לחזור עליו (${wrong.length})`),
        ...wrong.map(({ q, a }) => h('div', { class: 'review' },
          h('p', { class: 'q' }, rich(q.q)),
          h('div', { class: 'c bad' }, '✗ ענית: ', rich(a.t)),
          h('div', { class: 'c ok' }, '✓ נכון: ', rich(q.options.find(o => o.ok).t)),
          h('p', { class: 'small muted' }, rich(q.why)),
          h('a', { class: 'small', href: `#day-${q.day}` }, `← לחזרה על יום ${q.day}`)))) : null);
  }
}

function certificate(score) {
  const nameIn = h('input', { class: 'inp', type: 'text', maxlength: '40', placeholder: 'השם שלך לתעודה', 'aria-label': 'שם לתעודה', value: state.exam.name || '' });
  const nameOut = h('div', { class: 'cert-name' }, state.exam.name || 'הבוגר/ת');
  nameIn.addEventListener('input', () => {
    state.exam.name = nameIn.value.replace(/[\u0000-\u001f]/g, '').slice(0, 40);
    nameOut.textContent = state.exam.name || 'הבוגר/ת'; save();
  });
  const d = new Date();
  return h('section', { class: 'card' },
    h('div', { class: 'cert' },
      h('div', { class: 'cert-ico', 'aria-hidden': 'true' }, '🛡️'),
      h('div', { class: 'small muted' }, 'תעודת סיום'),
      h('h2', null, 'CyberQuest 14'),
      h('div', { class: 'muted' }, 'מוענקת בזאת ל'),
      nameOut,
      h('div', null, 'על השלמת מסלול סייבר ואבטחת מידע של 14 יום'),
      h('div', { class: 'muted small' }, 'רשתות · הצפנה · אימות · פישינג · נוזקות · כופרה · OWASP Top 10 · SOC'),
      h('div', { class: 'cert-foot' }, h('span', null, `ציון: ${score}`), h('span', null, `${d.getDate()}.${d.getMonth() + 1}.${d.getFullYear()}`))),
    h('div', { class: 'row', style: 'margin-top:10px' }, nameIn),
    h('p', { class: 'small muted' }, 'טיפ: צלם מסך של התעודה כדי לשמור או לשתף אותה.'));
}

// =====================================================================
//  ארגז כלים
// =====================================================================
function toolCard(title, desc, ...kids) { return h('section', { class: 'card tool' }, h('h3', null, title), h('p', { class: 'muted small' }, rich(desc)), ...kids); }
function kv(label, value) { return h('div', { class: 'kv' }, h('div', { class: 'k' }, label), h('code', { class: 'v' }, value)); }

function toolHash() {
  const ta = h('textarea', { class: 'inp', rows: '2', dir: 'auto', maxlength: '500', 'aria-label': 'טקסט לחישוב Hash' });
  ta.value = 'שלום';
  const out = h('div', { 'aria-live': 'polite' });
  let salt = '';
  function upd() {
    const t = ta.value;
    let b64 = '';
    try { b64 = btoa(String.fromCharCode(...new TextEncoder().encode(t))); } catch { b64 = '—'; }
    out.replaceChildren(kv('SHA-256 (חד-כיווני)', sha256(t)), kv('Base64 (קידוד — הפיך לכל אחד!)', b64 || '—'),
      ...(salt ? [kv(`SHA-256 עם Salt אקראי (${salt})`, sha256(salt + t))] : []));
  }
  ta.addEventListener('input', upd);
  const saltBtn = h('button', { class: 'btn', type: 'button' }, '🧂 הוסף Salt אקראי');
  saltBtn.addEventListener('click', () => { salt = randHex(8); upd(); });
  upd();
  return toolCard('🔬 מעבדת Hash חיה', 'שנה **תו אחד** וראה איך כל ה-Hash משתנה (אפקט המפולת). הוסף Salt וראה איך אותה סיסמה מקבלת Hash אחר לגמרי. הכל מחושב מקומית בדפדפן.', ta, out, saltBtn);
}

const COMMON = new Set(['123456', 'password', '123456789', '12345678', '12345', 'qwerty', 'qwerty123', '1q2w3e4r', '111111', '123123', 'abc123', 'password1', 'iloveyou', 'admin', 'welcome', 'monkey', 'dragon', 'sunshine', 'letmein', 'football', 'princess', 'master', 'shalom', 'shalom1', '000000', '1234567890', 'qwertyuiop', 'passw0rd', 'p@ssw0rd', 'summer', 'winter', 'login', 'starwars', 'baseball', 'superman', 'trustno1', 'hello', 'freedom', 'whatever', 'michael', 'aa123456', '666666', '654321', '987654321', 'changeme', 'secret', 'israel', 'computer']);
function assessPassword(pw) {
  const len = [...pw].length;
  const lower = pw.toLowerCase();
  const norm = lower.replace(/[@4]/g, 'a').replace(/3/g, 'e').replace(/[1!|]/g, 'i').replace(/0/g, 'o').replace(/[$5]/g, 's').replace(/7/g, 't');
  const cands = [lower, norm, lower.replace(/[\d\W_]+$/, ''), norm.replace(/[\d\W_]+$/, ''), lower.replace(/[^a-z]/g, '')].filter(c => c.length >= 4);
  const inList = COMMON.has(lower) || cands.some(c => COMMON.has(c) || COMMON.has(c.replace(/i/g, 'l')));
  const predictable = /(.)\1{2,}/.test(pw) || /(0123|1234|2345|3456|4567|5678|6789|abcd|qwer|asdf|zxcv)/i.test(pw);
  let pool = 0;
  if (/[a-z]/.test(pw)) pool += 26; if (/[A-Z]/.test(pw)) pool += 26; if (/\d/.test(pw)) pool += 10;
  if (/[^A-Za-z0-9֐-׿]/.test(pw)) pool += 33; if (/[֐-׿]/.test(pw)) pool += 27;
  let bits = len * Math.log2(Math.max(pool, 2));
  if (predictable) bits *= 0.6;
  if (inList) bits = Math.min(bits, 12);
  const score = bits < 28 ? 0 : bits < 40 ? 1 : bits < 60 ? 2 : bits < 80 ? 3 : 4;
  const secs = Math.pow(2, bits) / 1e10 / 2;
  return {
    bits, score, pct: Math.max(4, Math.min(100, Math.round(bits / 90 * 100))), time: fmtDuration(secs),
    items: [[len >= 15, `אורך ${len} — יעד NIST: 15+ תווים לסיסמה כגורם יחיד`], [len >= 8, 'לפחות 8 תווים (המינימום כשיש גם MFA)'],
      [!inList, inList ? 'מבוססת על סיסמה נפוצה/דלופה — תיפול במתקפת מילון' : 'לא נמצאה ברשימת הסיסמאות הנפוצות'],
      [!predictable, predictable ? 'יש רצף או חזרה צפויים (1234, aaa, qwer)' : 'אין רצפים צפויים']]
  };
}
function fmtDuration(s) {
  if (s < 1) return 'פחות משנייה ⚡';
  const units = [[60, 'שניות'], [60, 'דקות'], [24, 'שעות'], [365, 'ימים'], [1000, 'שנים']];
  let v = s;
  for (const [div, name] of units) { if (v < div) return `${Math.round(v)} ${name}`; v /= div; }
  return v < 1e6 ? `${Math.round(v)} אלפי שנים` : 'מיליוני שנים ומעלה 🛡️';
}
const PASS_WORDS = ['river', 'cactus', 'lamp', 'orbit', 'velvet', 'tiger', 'mango', 'pixel', 'harbor', 'violin', 'canyon', 'falcon', 'pepper', 'glacier', 'rocket', 'meadow', 'lemon', 'thunder', 'marble', 'coffee', 'shadow', 'bridge', 'castle', 'garden', 'planet', 'silver', 'island', 'forest', 'candle', 'dragonfly', 'zebra', 'puzzle', 'anchor', 'banjo', 'comet', 'desert', 'echo', 'feather', 'giraffe', 'hammock', 'igloo', 'jungle', 'koala', 'lantern', 'magnet', 'nectar', 'oyster', 'parrot', 'quartz', 'radar', 'saddle', 'tulip', 'umbrella', 'volcano', 'walnut', 'yogurt', 'zipper', 'basket', 'cobalt', 'dolphin', 'ember', 'fossil', 'granite', 'hazel'];
function passphrase(n = 6) {
  const a = new Uint32Array(n); crypto.getRandomValues(a);
  return Array.from(a, x => PASS_WORDS[x % PASS_WORDS.length]).join('-');
}
function toolPassword() {
  const inp = h('input', { class: 'inp', type: 'password', dir: 'ltr', maxlength: '128', autocomplete: 'off', spellcheck: 'false', placeholder: 'הקלד סיסמה לבדיקה', 'aria-label': 'סיסמה לבדיקה' });
  const eye = h('button', { class: 'btn', type: 'button', 'aria-label': 'הצג/הסתר סיסמה' }, '👁️');
  eye.addEventListener('click', () => { inp.type = inp.type === 'password' ? 'text' : 'password'; });
  const meter = h('div', { class: 'progress', style: 'margin-top:10px' }, h('span'));
  const res = h('div', { class: 'checks', 'aria-live': 'polite' });
  const colors = ['#F43F5E', '#FB923C', '#FBBF24', '#38BDF8', '#10B981'];
  const labels = ['חלשה מאוד', 'חלשה', 'בינונית', 'חזקה', 'חזקה מאוד'];
  function upd() {
    if (!inp.value) { meter.firstChild.style.width = '0'; res.replaceChildren(h('div', { class: 'muted small' }, 'התחל להקליד...')); return; }
    const a = assessPassword(inp.value);
    meter.firstChild.style.width = a.pct + '%'; meter.firstChild.style.background = colors[a.score];
    res.replaceChildren(h('div', null, h('strong', null, `חוזק: ${labels[a.score]}`)),
      ...a.items.map(([ok, t]) => h('div', { class: ok ? 'c ok' : 'c bad' }, (ok ? '✅ ' : '⚠️ ') + t)),
      h('div', { class: 'small muted' }, `⏳ זמן פיצוח משוער (אופליין, 10 מיליארד ניחושים/שנייה מול Hash מהיר): ${a.time}`));
  }
  inp.addEventListener('input', upd);
  const gen = h('button', { class: 'btn', type: 'button' }, '🎲 צור משפט סיסמה');
  gen.addEventListener('click', () => { inp.value = passphrase(); inp.type = 'text'; upd(); });
  upd();
  return toolCard('🔐 בודק חוזק סיסמה (לפי NIST)', 'הסיסמה **לא נשמרת ולא נשלחת לשום מקום** — הבדיקה כולה מקומית. ההערכה גסה ונועדה ללמידה; בפועל השתמש במנהל סיסמאות. (הגנרטור כאן מדגים בלבד — מנהלי סיסמאות משתמשים ברשימות מילים גדולות בהרבה.)',
    h('div', { class: 'row' }, inp, eye), meter, res, h('div', { class: 'row', style: 'margin-top:10px' }, gen));
}

function analyzeURL(raw) {
  raw = raw.trim().slice(0, 500);
  if (!raw) return null;
  let u;
  try { u = new URL(/^[a-z][a-z0-9+.-]*:/i.test(raw) ? raw : 'http://' + raw); } catch { return { error: 'זו לא כתובת תקינה' }; }
  if (!/^https?:$/.test(u.protocol)) return { error: 'הבודק תומך רק בכתובות http/https' };
  const host = u.hostname.toLowerCase();
  const labels = host.split('.');
  const isIP = /^\d{1,3}(\.\d{1,3}){3}$/.test(host) || host.startsWith('[');
  const sld = ['co.il', 'org.il', 'ac.il', 'gov.il', 'net.il', 'muni.il', 'co.uk', 'org.uk', 'com.au', 'co.jp', 'com.br'];
  let root = host;
  if (!isIP && labels.length >= 2) {
    const last2 = labels.slice(-2).join('.');
    root = sld.includes(last2) && labels.length >= 3 ? labels.slice(-3).join('.') : last2;
  }
  const items = [];
  items.push(u.protocol === 'https:' ? [true, 'HTTPS — החיבור מוצפן (אבל זה לא מוכיח שהאתר אמין)'] : [false, 'HTTP לא מוצפן — כל מי שבדרך יכול לקרוא ולשנות']);
  if (u.username || u.password) items.push([false, `יש טקסט לפני @ ("${decodeURIComponent(u.username)}") — הדפדפן מתעלם ממנו! היעד האמיתי: ${host}`]);
  if (isIP) items.push([false, 'כתובת IP במקום שם דומיין — חריג באתרים לגיטימיים']);
  if (host.includes('xn--')) items.push([false, 'Punycode (xn--) — ייתכן שהדומיין משתמש באותיות משפות אחרות שנראות זהות (Homograph)']);
  const sub = host.slice(0, Math.max(0, host.length - root.length - 1));
  const brands = ['microsoft', 'office', 'paypal', 'google', 'apple', 'icloud', 'amazon', 'facebook', 'instagram', 'whatsapp', 'netflix', 'leumi', 'hapoalim', 'mizrahi', 'discount', 'dhl', 'israelpost'];
  const b = brands.find(x => sub.includes(x) && !root.includes(x));
  if (b) items.push([false, `השם "${b}" מופיע רק בתת-הדומיין — הבעלים האמיתי הוא ${root}`]);
  if (/[a-z][01][a-z]|[a-z]{3}[01]\./.test(root)) items.push([false, 'ספרות 0/1 בתוך מילה — טריק חיקוי נפוץ (micros0ft, paypa1)']);
  if (labels.length >= 5) items.push([false, `הרבה תתי-דומיינים (${labels.length - 1} נקודות) — דרך נפוצה להסתיר את הדומיין האמיתי`]);
  const tld = labels[labels.length - 1];
  if (['zip', 'mov', 'top', 'xyz', 'click', 'country', 'gq', 'tk', 'ml', 'work', 'rest', 'cam'].includes(tld)) items.push([false, `הסיומת .${tld} נפוצה בקמפייני פישינג (לא הוכחה — אבל סיבה לזהירות)`]);
  if (u.port) items.push([false, `פורט לא סטנדרטי: ${u.port}`]);
  if (items.every(i => i[0])) items.push([true, 'לא נמצאו סימנים טכניים חשודים — עדיין ודא שזה בדיוק הדומיין שציפית לו']);
  return { host, root, items };
}
function toolURL() {
  const inp = h('input', { class: 'inp', type: 'url', dir: 'ltr', maxlength: '500', autocomplete: 'off', spellcheck: 'false', placeholder: 'https://example.com/login', 'aria-label': 'כתובת לבדיקה' });
  const out = h('div', { 'aria-live': 'polite' });
  function upd() {
    const r = analyzeURL(inp.value);
    if (!r) { out.replaceChildren(); return; }
    if (r.error) { out.replaceChildren(h('div', { class: 'c bad', style: 'margin-top:8px' }, '⚠️ ' + r.error)); return; }
    out.replaceChildren(h('div', { class: 'root-box' }, '🏠 הדומיין האמיתי (הבעלים): ', h('code', null, r.root)),
      h('div', { class: 'checks' }, r.items.map(([ok, t]) => h('div', { class: ok ? 'c ok' : 'c bad' }, (ok ? '✅ ' : '⚠️ ') + t))));
  }
  inp.addEventListener('input', upd);
  const examples = ['https://account.microsoft.com/security', 'http://account-microsoft.com.verify-login.ru/o365', 'https://paypal.com@evil.example/login', 'https://xn--80ak6aa92e.com', 'https://micros0ft-support.com'];
  const ex = h('div', { class: 'ex-links' }, examples.map(x => h('button', { class: 'btn', type: 'button', onclick: () => { inp.value = x; upd(); } }, x)));
  return toolCard('🔗 מפרק כתובות (URL Inspector)', 'הדבק קישור (בלי ללחוץ עליו!) וגלה מי **באמת** הבעלים של הדומיין. הבדיקה מקומית בלבד — שום כתובת לא נפתחת.', inp, out, h('div', { class: 'muted small', style: 'margin-top:10px' }, 'נסה דוגמאות:'), ex);
}
const TOOLS = { hash: toolHash, password: toolPassword, url: toolURL };

function renderTools(v) {
  v.append(h('h1', null, '🧰 ארגז הכלים של המגן'), h('p', { class: 'muted' }, 'כלים אמיתיים שעובדים מקומית בדפדפן — לתרגול חופשי בכל זמן.'), toolURL(), toolPassword(), toolHash());
}

// =====================================================================
//  תזכורות: Web Notifications + קובץ יומן ICS + Google Calendar
// =====================================================================
let reminderTimer = null;
const ICON_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="112" fill="#0F172A"/><path d="M256 76l150 56v108c0 96-64 166-150 196-86-30-150-100-150-196V132z" fill="#10B981"/><path d="M196 262l44 44 84-92" fill="none" stroke="#0F172A" stroke-width="34" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const ICON_URL = 'data:image/svg+xml,' + encodeURIComponent(ICON_SVG);

function scheduleReminder() {
  clearTimeout(reminderTimer);
  if (!state.reminder.enabled) return;
  const [hh, mm] = state.reminder.time.split(':').map(Number);
  const now = new Date(), t = new Date();
  t.setHours(hh, mm, 0, 0);
  if (t <= now) t.setDate(t.getDate() + 1);
  reminderTimer = setTimeout(() => { fireReminder(); scheduleReminder(); }, Math.min(t - now, 2147483000));
}
function fireReminder() {
  if (learnedToday()) return;
  const nd = nextDay();
  const body = `יום ${nd.id}: ${nd.title} — 5 דקות ושומרים על הרצף 🔥`;
  if ('Notification' in window && Notification.permission === 'granted') {
    try { new Notification('🛡️ CyberQuest – הגיע זמן ללמוד!', { body, icon: ICON_URL, tag: 'cq-daily' }); } catch { /* בנייד נדרשת התקנה כאפליקציה */ }
  }
  mascot('wow', `⏰ תזכורת! ${body}`, 9000);
}
function icsStamp(d) { return d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, ''); }
function localStamp(d) { const p = n => String(n).padStart(2, '0'); return `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}T${p(d.getHours())}${p(d.getMinutes())}00`; }
function reminderStart() { const [hh, mm] = state.reminder.time.split(':').map(Number); const d = new Date(); d.setHours(hh, mm, 0, 0); return d; }
const tzName = () => { try { return Intl.DateTimeFormat().resolvedOptions().timeZone || 'Asia/Jerusalem'; } catch { return 'Asia/Jerusalem'; } };
function buildICS() {
  const start = reminderStart();
  return ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//CyberQuest14//HE', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH',
    'BEGIN:VEVENT', `UID:cyberquest14-${Date.now()}-${randHex(4)}@local`, `DTSTAMP:${icsStamp(new Date())}`,
    `DTSTART;TZID=${tzName()}:${localStamp(start)}`, 'DURATION:PT15M', 'RRULE:FREQ=DAILY;COUNT=14',
    'SUMMARY:🛡️ CyberQuest – שיעור סייבר יומי', 'DESCRIPTION:5 דקות קריאה + מעבדת תוקף ומגן. שמור על הרצף!',
    'BEGIN:VALARM', 'ACTION:DISPLAY', 'DESCRIPTION:זמן ללמוד סייבר!', 'TRIGGER:-PT0M', 'END:VALARM',
    'END:VEVENT', 'END:VCALENDAR', ''].join('\r\n');
}
function gcalURL() {
  const s = reminderStart(), e = new Date(s.getTime() + 15 * 60000);
  const p = new URLSearchParams({ action: 'TEMPLATE', text: '🛡️ CyberQuest – שיעור סייבר יומי', details: '5 דקות קריאה + מעבדת תוקף ומגן. שמור על הרצף!',
    dates: `${localStamp(s)}/${localStamp(e)}`, ctz: tzName(), recur: 'RRULE:FREQ=DAILY;COUNT=14' });
  return 'https://calendar.google.com/calendar/render?' + p.toString();
}

// =====================================================================
//  PWA: Manifest + התקנה
// =====================================================================
let deferredPrompt = null;
const isStandalone = () => matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
function setupPWA() {
  const base = location.href.split('#')[0];
  const manifest = { name: 'CyberQuest 14 – לומדים סייבר', short_name: 'CyberQuest', description: 'לומדים סייבר ואבטחת מידע ב-14 יום',
    start_url: base, scope: base.replace(/[^/]*$/, ''), display: 'standalone', orientation: 'portrait',
    background_color: '#0F172A', theme_color: '#0F172A', lang: 'he', dir: 'rtl',
    icons: [{ src: ICON_URL, sizes: 'any', type: 'image/svg+xml', purpose: 'any' }] };
  const url = URL.createObjectURL(new Blob([JSON.stringify(manifest)], { type: 'application/manifest+json' }));
  document.head.append(h('link', { rel: 'manifest', href: url }), h('link', { rel: 'icon', href: ICON_URL, type: 'image/svg+xml' }), h('link', { rel: 'apple-touch-icon', href: ICON_URL }));
  window.addEventListener('beforeinstallprompt', e => { e.preventDefault(); deferredPrompt = e; });
  window.addEventListener('appinstalled', () => { deferredPrompt = null; toast('📲 האפליקציה הותקנה!', 'xp'); });
}
async function installApp() {
  if (deferredPrompt) {
    deferredPrompt.prompt();
    try { const { outcome } = await deferredPrompt.userChoice; if (outcome === 'accepted') mascot('happy', 'יש! עכשיו אני גר אצלך במסך הבית 🏠', 5000); } catch { /* ignore */ }
    deferredPrompt = null;
  } else {
    location.hash = '#prefs';
    setTimeout(() => $('#install-card')?.scrollIntoView({ behavior: 'smooth' }), 100);
    mascot('think', 'הדפדפן לא הציע התקנה אוטומטית — הנה ההוראות הידניות 👇 (לוקח 10 שניות)', 6000);
  }
}

// =====================================================================
//  מסך הגדרות
